+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+type Temperature = (typeof TEMPERATURE_UNITS)[number];
+
+const ABSOLUTE_ZERO: Record<Temperature, number> = { C: -273.15, F: -459.67, K: 0 };
+
+function isTemperature(unit: string): unit is Temperature {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(unit);
+}
+
+function kindOf(unit: string): string {
+  if (Object.hasOwn(LINEAR_UNITS, unit)) return LINEAR_UNITS[unit].kind;
+  if (isTemperature(unit)) return "temperature";
+  throw new Error(`unknown unit: ${unit}`);
+}
+
+function toCelsius(value: number, unit: Temperature): number {
+  switch (unit) {
+    case "C":
+      return value;
+    case "F":
+      return ((value - 32) * 5) / 9;
+    case "K":
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: Temperature): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    case "K":
+      return celsius + 273.15;
+  }
+}
+
+function convertTemperature(value: number, from: Temperature, to: Temperature): number {
+  if (value < ABSOLUTE_ZERO[from]) throw new RangeError(`${value} ${from} is below absolute zero`);
+  if (from === to) return value;
+  return fromCelsius(toCelsius(value, from), to);
+}
